ALTER TABLE users DROP CONSTRAINT users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN('super_admin','admin','viewer'));
UPDATE users SET role='super_admin' WHERE id=(SELECT id FROM users WHERE role='admin' ORDER BY created_at,id LIMIT 1);
ALTER TABLE import_runs DROP CONSTRAINT import_runs_status_check;
ALTER TABLE import_runs ADD CONSTRAINT import_runs_status_check CHECK(status IN('preparing','preview','pending','complete','failed','cancelled'));
ALTER TABLE import_runs ADD COLUMN context JSONB NOT NULL DEFAULT '{}';
ALTER TABLE import_runs ADD COLUMN preview JSONB;
ALTER TABLE import_runs ADD COLUMN config_digest TEXT;
CREATE TABLE managed_entities(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('account','accountant','client','contact','group','binding')),payload JSONB NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX managed_entities_kind ON managed_entities(kind);
CREATE UNIQUE INDEX managed_account_phone ON managed_entities((payload->>'phone')) WHERE kind='account';
CREATE UNIQUE INDEX managed_group_jid ON managed_entities((payload->>'chatId')) WHERE kind='group';
CREATE UNIQUE INDEX managed_party_contact ON managed_entities((payload->>'partyId'),(payload->>'phone')) WHERE kind='contact';
CREATE TABLE routing_versions(id TEXT PRIMARY KEY,binding_id TEXT NOT NULL REFERENCES managed_entities(id),config JSONB NOT NULL,effective_from TIMESTAMPTZ NOT NULL,effective_until TIMESTAMPTZ,approved_at TIMESTAMPTZ NOT NULL,actor TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX routing_source_time ON routing_versions((config->>'sourceId'),effective_from,effective_until);
CREATE TABLE message_changes(id TEXT PRIMARY KEY,message_id TEXT NOT NULL REFERENCES messages(id),content_hash TEXT NOT NULL,body TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',file_id TEXT REFERENCES source_files(id),review_id TEXT REFERENCES reviews(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(message_id,content_hash));
CREATE TABLE import_items(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),item_key TEXT NOT NULL,content_hash TEXT NOT NULL,anchor TEXT NOT NULL,payload JSONB NOT NULL,file_id TEXT REFERENCES source_files(id),record_id TEXT REFERENCES records(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,item_key));
CREATE INDEX import_items_anchor ON import_items(source_id,anchor);
CREATE TABLE import_item_changes(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES import_items(id),content_hash TEXT NOT NULL,payload JSONB NOT NULL,file_id TEXT REFERENCES source_files(id),review_id TEXT REFERENCES reviews(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(item_id,content_hash));
ALTER TABLE employees ADD COLUMN status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive'));
ALTER TABLE employees ADD COLUMN role TEXT NOT NULL DEFAULT 'Employee';
ALTER TABLE employees ADD COLUMN notes TEXT NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE employees ADD COLUMN updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE reviews ADD COLUMN domain TEXT NOT NULL DEFAULT 'identity';
CREATE OR REPLACE VIEW programs AS SELECT id,payload->>'motherVessel' AS mother_vessel,payload->>'lighterVessel' AS lighter_vessel,payload->>'masterMobile' AS master_mobile,payload->>'escortName' AS escort_name,payload->>'escortMobile' AS escort_mobile,payload->>'startDate' AS start_date,payload->>'shift' AS start_shift,payload->>'endDate' AS end_date,payload->>'endShift' AS end_shift,payload->>'releasePoint' AS release_point,payload->>'destination' AS destination,payload->>'status' AS status,revision,deleted_at,payload->>'clientId' AS client_id,payload->>'clientName' AS client_name,payload->>'masterName' AS master_name,CASE WHEN payload->>'status'='Draft' THEN 'draft' ELSE 'recorded' END AS program_stage FROM records WHERE kind='program';
CREATE TABLE managed_entity_versions(id TEXT PRIMARY KEY,entity_id TEXT NOT NULL REFERENCES managed_entities(id),kind TEXT NOT NULL,payload JSONB NOT NULL,effective_from TIMESTAMPTZ NOT NULL,effective_until TIMESTAMPTZ,approved_at TIMESTAMPTZ NOT NULL,actor TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX managed_entity_timeline ON managed_entity_versions(entity_id,effective_from,effective_until);
